{
  "items": [
    {
      "name": "norm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_9} [inst : SeminormedAddCommGroup E] (s : Finset ι) (f : ι → E),\n  ‖∑ i ∈ s, f i‖ ≤ ∑ i ∈ s, ‖f i‖"
    },
    {
      "name": "norm_sum_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) {f : ι → E} {n : ι → ℝ},\n  (∀ b ∈ s, ‖f b‖ ≤ n b) → ‖∑ b ∈ s, f b‖ ≤ ∑ b ∈ s, n b"
    },
    {
      "name": "nnnorm_sum_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) {f : ι → E} {n : ι → NNReal},\n  (∀ b ∈ s, ‖f b‖₊ ≤ n b) → ‖∑ b ∈ s, f b‖₊ ≤ ∑ b ∈ s, n b"
    },
    {
      "name": "enorm_sum_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {ε : Type u_8} [inst : TopologicalSpace ε] [inst_1 : ESeminormedAddCommMonoid ε] (s : Finset ι)\n  {f : ι → ε} {n : ι → ENNReal}, (∀ b ∈ s, ‖f b‖ₑ ≤ n b) → ‖∑ b ∈ s, f b‖ₑ ≤ ∑ b ∈ s, n b"
    },
    {
      "name": "nnnorm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) (f : ι → E),\n  ‖∑ a ∈ s, f a‖₊ ≤ ∑ a ∈ s, ‖f a‖₊"
    },
    {
      "name": "MeasureTheory.eLpNorm'_sum_le",
      "module_name": "Mathlib.MeasureTheory.Function.LpSeminorm.TriangleInequality",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ε' : Type u_4} {m : MeasurableSpace α} [inst : TopologicalSpace ε']\n  [inst_1 : ESeminormedAddCommMonoid ε'] {q : ℝ} {μ : MeasureTheory.Measure α} [ContinuousAdd ε'] {ι : Type u_5}\n  {f : ι → α → ε'} {s : Finset ι},\n  (∀ i ∈ s, MeasureTheory.AEStronglyMeasurable (f i) μ) →\n    1 ≤ q → MeasureTheory.eLpNorm' (∑ i ∈ s, f i) q μ ≤ ∑ i ∈ s, MeasureTheory.eLpNorm' (f i) q μ"
    },
    {
      "name": "enorm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {ε : Type u_9} [inst : TopologicalSpace ε] [inst_1 : ESeminormedAddCommMonoid ε] (s : Finset ι)\n  (f : ι → ε), ‖∑ i ∈ s, f i‖ₑ ≤ ∑ i ∈ s, ‖f i‖ₑ"
    },
    {
      "name": "norm_multiset_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {E : Type u_9} [inst : SeminormedAddCommGroup E] (m : Multiset E), ‖m.sum‖ ≤ (Multiset.map (fun x => ‖x‖) m).sum"
    }
  ]
}
